import pandas as pd
import numpy as np
from scipy import stats

# Load all experiments
dfs = {}
for i in [1, 3, 5, 6, 7, 9]:
    try:
        dfs[f"exp{i}"] = pd.read_csv(f"experiment_{i}_csv")
        print(f"exp{i}: {dfs[f'exp{i}'].shape}")
    except:
        print(f"exp{i}: not found or error")

# Examine what each experiment has
for name, df in dfs.items():
    print(f"\n=== {name} columns ===")
    print(df.columns.tolist())
    if 'CropYield' in df.columns:
        print(f"  CropYield stats: mean={df['CropYield'].mean():.2f}, std={df['CropYield'].std():.2f}")
    # Show any intervention columns (starting with do_)
    for col in df.columns:
        if col.startswith('do_'):
            print(f"  Intervention {col}: unique values = {df[col].unique()}")

# Correlate TissueNutrientAssay with CropYield where both exist
for name in ['exp7', 'exp9']:
    if name in dfs:
        df = dfs[name]
        if 'TissueNutrientAssay' in df.columns and 'CropYield' in df.columns:
            r, p = stats.pearsonr(df['TissueNutrientAssay'], df['CropYield'])
            print(f"\n{name}: TissueNutrientAssay vs CropYield: r={r:.3f}, p={p:.2e}")
        if 'CanopyTemp' in df.columns and 'CropYield' in df.columns:
            r, p = stats.pearsonr(df['CanopyTemp'], df['CropYield'])
            print(f"{name}: CanopyTemp vs CropYield: r={r:.3f}, p={p:.2e}")

# Check if CanopyTemp is a confound or causal
# If CanopyTemp drives yield, it should be responsive to interventions
